package ai.eva.android.probe;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;

/** API credentials are entered only in this native window. */
public class ModelsActivity extends ToolPageActivity {
 ModelStore store;String editing="";EditText name,url,model,apiKey;TextView message;Button pasteKey;boolean busy;
 public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);store=new ModelStore(this);page("API 提供商","");listing();}
 LinearLayout content(){clear();ScrollView scroll=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(1);scroll.addView(box);body.addView(scroll,new LinearLayout.LayoutParams(-1,-1));return box;}
 void listing(){editing="";name=null;LinearLayout box=content();try{JSONObject config=store.publicConfig();JSONArray list=config.getJSONArray("providers");box.addView(label("沿用桌面 Eva 的 Responses API 接入方式",12));box.addView(button("添加提供商",()->editor("")));if(list.length()==0)box.addView(label("还没有提供商。添加 API 地址、密钥和模型后，可测试连接并用于对话。",14));for(int i=0;i<list.length();i++){JSONObject p=list.getJSONObject(i);String id=p.getString("id");box.addView(button(p.getString("name")+(id.equals(config.optString("active"))?" · 默认":"")+"\n"+p.getString("model"),()->editor(id)));}}catch(Exception e){box.addView(label("配置读取失败，请重新打开或重新配置",14));}}
 EditText field(LinearLayout box,String title,String value,String hint,int type){box.addView(label(title,12));EditText edit=new EditText(this);edit.setTextSize(14);edit.setTextColor(ink);edit.setHintTextColor(0xff858b92);edit.setInputType(type);edit.setSingleLine();edit.setText(value);edit.setHint(hint);edit.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);box.addView(edit);return edit;}
 void editor(String id){editing=id;LinearLayout box=content();try{JSONObject p=id.isEmpty()?new JSONObject():store.provider(id);name=field(box,"名称",p.optString("name"),"例如：我的 API 服务",1);url=field(box,"API 基础地址",p.optString("url"),"https://服务域名/v1",17);model=field(box,"模型 ID",p.optString("model"),"输入服务商提供的模型 ID",1);apiKey=field(box,"API Key","",id.isEmpty()?"仅保存在此手机":"已保存；留空保留原密钥",129);apiKey.setImeOptions(android.view.inputmethod.EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING);apiKey.setTransformationMethod(android.text.method.PasswordTransformationMethod.getInstance());apiKey.setLongClickable(true);pasteKey=button("粘贴 API Key",()->pasteApiKey());box.addView(pasteKey);box.addView(label("密钥由 Android Keystore 加密，不返回会话网页。更换服务地址时必须重新填写密钥。",11));message=label("",12);box.addView(message);
 box.addView(button("保存",()->save()));box.addView(button("保存并获取模型列表",()->test(true)));box.addView(button("保存并测试连接",()->test(false)));box.addView(button("设为默认模型",()->{if(save())try{store.select(editing);message.setText("已设为默认；新会话使用此模型，已有会话保留原模型");}catch(Exception e){message.setText("选择失败");}}));
 if(!id.isEmpty())box.addView(button("删除提供商",()->{if(busy)return;new AlertDialog.Builder(this).setTitle("删除此提供商？").setMessage("将移除本机密钥。使用它的已有会话将无法继续调用，聊天记录会保留。").setPositiveButton("删除",(d,w)->{try{store.delete(id);listing();}catch(Exception e){message.setText("删除失败");}}).setNegativeButton("取消",null).show();}));
 }catch(Exception e){box.addView(label("提供商读取失败",14));}}
 void pasteApiKey(){
  apiKey.requestFocus();
  try{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);android.content.ClipData clip=clipboard.getPrimaryClip();CharSequence value=clip!=null&&clip.getItemCount()>0?clip.getItemAt(0).getText():null;
   if(value==null||value.length()==0){Toast.makeText(this,"剪贴板中没有可粘贴的文本，请先复制 API Key",Toast.LENGTH_SHORT).show();return;}
   int start=apiKey.getSelectionStart(),end=apiKey.getSelectionEnd();if(start<0||end<0){start=end=apiKey.length();}int from=Math.min(start,end),to=Math.max(start,end);apiKey.getText().replace(from,to,value);apiKey.setSelection(Math.min(from+value.length(),apiKey.length()));
  }catch(Exception e){Toast.makeText(this,"暂时无法读取剪贴板，请重新复制后再试",Toast.LENGTH_SHORT).show();}
 }
 boolean save(){if(busy){message.setText("正在请求，请稍候");return false;}try{editing=store.save(editing,name.getText().toString(),url.getText().toString(),model.getText().toString(),apiKey.getText().toString());apiKey.setText("");apiKey.setHint("已保存；留空保留原密钥");message.setText("已保存。若内核已启动，请重启 Eva 后使用新配置。连接测试可能计费。");return true;}catch(Exception e){message.setText(e instanceof java.io.IOException?e.getMessage():"凭据保存失败，请检查设备密钥存储");return false;}}
 void test(boolean discover){if(!discover&&model.getText().toString().trim().isEmpty()){message.setText("请先填写模型 ID，或获取模型列表后选择");return;}if(!save())return;busy=true;message.setText(discover?"正在获取模型列表…":"正在测试 Responses 调用…");final String id=editing;ModelClient.workers.execute(()->{try{JSONObject provider=store.provider(id);JSONObject response=ModelClient.request(provider,store.secret(provider),discover?"models":"responses",discover?null:new JSONObject().put("model",provider.getString("model")).put("input","Reply with exactly: pong").put("store",false).put("stream",false),new ModelClient.Job());
 if(discover){JSONArray data=response.optJSONArray("data");if(data==null)throw new java.io.IOException("服务未返回模型列表");java.util.ArrayList<String> models=new java.util.ArrayList<>();for(int i=0;i<data.length()&&models.size()<500;i++){JSONObject m=data.optJSONObject(i);if(m!=null&&!m.optString("id").isEmpty())models.add(m.getString("id"));}runOnUiThread(()->{if(isFinishing()||!editing.equals(id))return;message.setText("获取到 "+models.size()+" 个模型；列表存在不代表账号有调用权限");if(!models.isEmpty())new AlertDialog.Builder(this).setTitle("选择模型").setItems(models.toArray(new String[0]),(d,n)->{model.setText(models.get(n));save();}).setNegativeButton("取消",null).show();});}
 else{ModelClient.text(response);runOnUiThread(()->{if(!isFinishing()&&editing.equals(id))message.setText("连接成功：Responses 文本调用已完成");});}
 }catch(Exception e){String error=ModelClient.safeError(e);runOnUiThread(()->{if(!isFinishing()&&editing.equals(id))message.setText(error);});}finally{busy=false;}});}
 void leavePage(){onBackPressed();}
 public void onBackPressed(){if(busy){Toast.makeText(this,"请求仍在进行，请稍候",Toast.LENGTH_SHORT).show();return;}if(!editing.isEmpty()||name!=null){name=null;listing();return;}finish();}
}
